const LANGUAGES=['pt','en','es','fr','it'];
const DICTIONARIES=Object.fromEntries(LANGUAGES.slice(1).map((lang,index)=>[lang,new Map(COPY.map(row=>[row[0],row[index+1]]))]));
const KEYS=[...COPY.map(([pt])=>pt)].sort((a,b)=>b.length-a.length);

export function createPDFI18n(language='pt'){
 const lang=LANGUAGES.includes(language)?language:'pt',locale={pt:'pt-PT',en:'en-GB',es:'es-ES',fr:'fr-FR',it:'it-IT'}[lang];
 const bedrooms=count=>({en:`${count} ${count==='1'?'bedroom':'bedrooms'} · 1 bathroom`,es:`${count} ${count==='1'?'dormitorio':'dormitorios'} · 1 baño`,fr:`${count} ${count==='1'?'chambre':'chambres'} · 1 salle de bains`,it:`${count} ${count==='1'?'camera da letto':'camere da letto'} · 1 bagno`}[lang]);
 function t(value){
  if(value?.[RAW])return value.value;
  const source=String(value??'');if(lang==='pt')return source;
  const dictionary=DICTIONARIES[lang];if(dictionary.has(source))return dictionary.get(source);
  const numbered=source.match(/^(\d+\.\s+)(.+)$/s);if(numbered)return numbered[1]+t(numbered[2]);
  if(source.includes('\n'))return source.split('\n').map(t).join('\n');
  const assigned=source.match(/^(\d+) de (\d+)( por atribuir)?\.?$/);
  if(assigned)return {en:`${assigned[1]} of ${assigned[2]}${assigned[3]?' to be assigned':''}.`,es:`${assigned[1]} de ${assigned[2]}${assigned[3]?' pendientes de asignar':''}.`,fr:`${assigned[1]} sur ${assigned[2]}${assigned[3]?' à attribuer':''}.`,it:`${assigned[1]} di ${assigned[2]}${assigned[3]?' da assegnare':''}.`}[lang];
  const clientPage=source.match(/^Planta do cliente · página (\d+) de (\d+)$/);
  if(clientPage)return {en:`Client floor plan · page ${clientPage[1]} of ${clientPage[2]}`,es:`Plano del cliente · página ${clientPage[1]} de ${clientPage[2]}`,fr:`Plan du client · page ${clientPage[1]} sur ${clientPage[2]}`,it:`Planimetria del cliente · pagina ${clientPage[1]} di ${clientPage[2]}`}[lang];
  const extra=source.match(/^O modelo 3D representa uma frente\. As restantes (\d+) unidades são pedidos adicionais, com aplicação sujeita a validação\.$/);
  if(extra)return {en:`The 3D model shows one front. The remaining ${extra[1]} units are additional requests, with application subject to validation.`,es:`El modelo 3D representa un frente. Las ${extra[1]} unidades restantes son solicitudes adicionales cuya aplicación está sujeta a validación.`,fr:`Le modèle 3D représente une façade avant. Les ${extra[1]} unités restantes sont des demandes supplémentaires, dont l’installation est soumise à validation.`,it:`Il modello 3D rappresenta una facciata anteriore. Le restanti ${extra[1]} unità sono richieste aggiuntive, la cui installazione è soggetta a verifica.`}[lang];
  const counts=source.match(/^(\d+) quartos? · 1 casa de banho · (telhado triangular|cobertura plana)( · alpendre seleccionado)?$/);
  if(counts){
   const roofs={en:['gable roof','flat roof','porch selected'],es:['tejado a dos aguas','cubierta plana','porche seleccionado'],fr:['toit à deux pans','toit plat','porche sélectionné'],it:['tetto a due falde','copertura piana','portico selezionato']}[lang];
   return `${bedrooms(counts[1])} · ${roofs[counts[2]==='telhado triangular'?0:1]}${counts[3]?' · '+roofs[2]:''}`;
  }
  // Consume source phrases once, without feeding translated output back through
  // phrase replacement (for example 'Local' must not mutate English 'Locations').
  const translated=translateText(source,lang);let result='',position=0;
  while(position<translated.length){
   const key=KEYS.find(key=>translated.startsWith(key,position)&&(!position||!/[\p{L}]/u.test(translated[position-1]))&&(!/[\p{L}]/u.test(key.at(-1))||!/[\p{L}]/u.test(translated[position+key.length]||'')));
   if(key){result+=dictionary.get(key);position+=key.length;}else{result+=translated[position++];}
  }
  return result.replace(/(\d+) quartos? · 1 casa de banho/g,(_,count)=>bedrooms(count)).split(/(\s+[·—]\s+|;\s*|:\s*|\n|(?<=\.)\s+)/u).map((part,index)=>{
   if(index%2)return part;
   const translated=translateText(part,lang);if(translated!==part)return translated;
   if(part.endsWith('.'))return translateText(part.slice(0,-1),lang)+'.';
   return part;
  }).join('');
 }
 const date=value=>{const parsed=value instanceof Date?value:new Date(String(value).slice(0,10)+'T12:00:00Z');return Number.isNaN(parsed.valueOf())?String(value):new Intl.DateTimeFormat(locale).format(parsed);};
 const money=cents=>cents===null||cents===undefined?t('Sob consulta'):new Intl.NumberFormat(locale,{style:'currency',currency:'EUR',minimumFractionDigits:2,maximumFractionDigits:2}).format(cents/100);
 return {lang,locale,t,date,money,raw:rawPDF};
}
